import {languages,translate} from './i18n.js';
import {emptyTracker,emptyAccount,sampleTracker,validateTracker,validateAccount,attention,orderedAccounts,counts,familySummary,SOURCES,today,validDate} from './tracker.js';
import {sealCase,openCase,download} from './privacy.js';
const codes=languages.map(([code])=>code),pathLanguage=()=>location.pathname.replace(/\/$/,'').slice(1);
let lang=codes.includes(pathLanguage())?pathLanguage():'en',chosen=codes.includes(pathLanguage());
if(codes.includes(pathLanguage()))history.replaceState({virasatLanguage:lang},'', '/');
let current=emptyTracker(),view='home',selected='',draft=null,unfinishedDraft=null,unfinishedStep=0,step=0,generation=0;
const main=document.querySelector('main'),live=document.querySelector('#live'),t=k=>translate(lang,k);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>new Intl.NumberFormat(lang+'-IN').format(n);
const date=s=>s?new Intl.DateTimeFormat(lang+'-IN',{day:'numeric',month:'short',year:'numeric'}).format(new Date(s+'T00:00:00Z')):t('neverChecked');
const button=(id,key,cls='secondary')=>`<button type="button" id="${id}" class="${key==='back'?'back-button':cls}">${key==='back'?'<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m14 6-6 6 6 6"/></svg>':''}<span>${t(key)}</span></button>`;
const icons={bank:'<path d="m3 9 9-5 9 5M4 20h16M6 11v6m6-6v6m6-6v6"/>',demat:'<path d="m3 7 9-4 9 4-9 4-9-4Zm0 5 9 4 9-4M3 17l9 4 9-4"/>',mf:'<path d="M12 3v9h9A9 9 0 0 0 12 3Z"/><path d="M8 4a9 9 0 1 0 12 12"/>',arrow:'<path d="m9 5 7 7-7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9H3V7Z"/><path d="M3 11h18"/>',check:'<path d="m5 12 4 4 10-10"/>'};
const icon=(name)=>`<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.folder}</svg>`;
const selectedAccount=()=>current.accounts.find(a=>a.id===selected);
const accountTitle=a=>a.label||a.institution;
const taskKey=a=>({missing:'registerTask',unknown:'checkTask',awaiting:'confirmTask',review:'checkTask',confirmed:'recordTask'}[attention(a)]);
const title=(heading,intro='')=>`<div class="page-heading"><h1>${heading}</h1>${intro?`<p>${intro}</p>`:''}</div>`;
function status(a){return `<span class="status-pill status-${attention(a)}"><span>${t(attention(a))}</span></span>`;}
function accountRow(a,summary=false){return `<${summary?'article':'button'} ${summary?'':`type="button" data-account="${a.id}"`} class="account-row"><span class="account-symbol">${icon(a.type)}</span><span class="account-row-main"><strong>${esc(accountTitle(a))}</strong><span>${esc(a.label?a.institution:'')}${a.owner?` · ${esc(a.owner)}`:''}${a.last4?` · •••• ${a.last4}`:''}</span><span class="account-meta">${t(a.type)} · ${t(a.review)}</span></span><span class="account-row-status">${status(a)}</span>${summary?'':`<span class="row-arrow">${icon('arrow')}</span>`}</${summary?'article':'button'}>`;}
function list(){const n=counts(current),unfinished=unfinishedDraft||(draft&&!current.accounts.some(a=>a.id===draft.id));return `${title(t('homeTitle'),t('homeIntro'))}<div class="home-actions">${button('add','add','primary')}${!n.total?button('resume','resume','text-button'):button('summary','summary','text-button')}${n.total?button('save','saveShort','text-button'):''}</div>${unfinished?`<button type="button" id="continue-draft" class="unfinished-link">${t('unfinished')} ${icon('arrow')}</button>`:''}${n.total?`<section class="account-list"><div class="list-heading"><h2>${t('accounts')} <span>${num(n.total)}</span></h2>${current.synthetic?`<span class="sample-label">${t('sample')}</span>`:''}</div><div class="account-rows">${orderedAccounts(current.accounts).map(a=>accountRow(a)).join('')}</div><p class="list-foot">${t('selfReport')}</p></section>`:`<div class="empty-note"><p>${t('emptyIntro')}</p><div class="example-types">${['demat','bank','mf'].map(k=>`<span>${icon(k)}${t(k)}</span>`).join('')}</div>${button('demo','example','text-button')}</div>`}`;}
const inputHint={institution:'institutionExample',label:'nicknameExample',owner:'ownerExample',nomineeNote:'nomineeNoteExample',last4:'last4Example',recordNote:'recordNoteExample'};
function field(name,key,type='text',required=false){if(type==='date')return dateField(name,key);const hint=inputHint[name];return `<div class="field"><label for="account-${name}">${t(key)}</label><input id="account-${name}" name="${name}" type="${type}" value="${esc(draft[name])}" maxlength="${name==='last4'?4:name==='recordNote'?160:80}" ${required?'required':''} aria-describedby="${hint?`account-${name}-hint `:''}account-${name}-error" ${hint?`placeholder="${esc(t(hint))}"`:''} ${name==='last4'?'inputmode="numeric"':''}>${hint?`<p class="help" id="account-${name}-hint">${t(hint)}</p>`:''}<p id="account-${name}-error" class="error field-error" role="alert"></p></div>`;}
function dateParts(name){if(!draft._dateParts)draft._dateParts={};if(!draft._dateParts[name]){const [year='',month='',day='']=(draft[name]||'').split('-');draft._dateParts[name]={day,month,year};}return draft._dateParts[name];}
function dateField(name,key){const parts=dateParts(name);return `<fieldset class="date-field"><legend>${t(key)}</legend><div class="date-parts">${['day','month','year'].map(part=>`<div><label for="account-${name}-${part}">${t(part)}</label><input id="account-${name}-${part}" data-date-name="${name}" data-date-part="${part}" type="text" inputmode="numeric" maxlength="${part==='year'?4:2}" value="${esc(parts[part])}" placeholder="${part==='day'?'14':part==='month'?'09':'2026'}" aria-describedby="account-${name}-hint account-${name}-error"></div>`).join('')}</div><p class="help" id="account-${name}-hint">${t(name==='submittedOn'?'submissionExample':'dateExample')}</p><p id="account-${name}-error" class="error field-error" role="alert"></p></fieldset>`;}
function recordChoices(){return `<fieldset class="record-options"><legend>${t('recordKind')}</legend>${['statement','registration'].map(k=>`<label><input id="record-${k}" name="recordKind" type="radio" value="${k}" ${draft.recordKind===k?'checked':''} aria-describedby="record-${k}-hint account-recordKind-error"><span><strong>${t(k)}</strong><span id="record-${k}-hint">${t(k+'Example')}</span></span></label>`).join('')}<p id="account-recordKind-error" class="error field-error" role="alert"></p></fieldset>`;}
function typeChoices(){return `<fieldset class="type-options"><legend class="sr-only">${t('type')}</legend>${['demat','bank','mf'].map(k=>`<label><input type="radio" name="type" value="${k}" ${draft.type===k?'checked':''}><span class="type-icon">${icon(k)}</span><span><strong>${t(k)}</strong><span>${t(k+'Description')}</span></span></label>`).join('')}</fieldset>`;}
function nomineeChoices(){return `<fieldset class="nomination-options"><legend class="${current.accounts.some(a=>a.id===draft.id)?'':'sr-only'}">${t('nomination')}</legend><div class="answer-options">${['registered','missing','unknown'].map(k=>`<label><input type="radio" name="nomination" value="${k}" ${draft.nomination===k?'checked':''}><span>${t({registered:'nomineeYes',missing:'nomineeNo',unknown:'unknown'}[k])}</span></label>`).join('')}</div></fieldset>`;}
function optionalFields(){return `<details id="account-extra"><summary>${t('extra')}</summary><div class="detail-body"><div class="form-grid">${field('label','nickname')}${field('owner','owner')}${field('nomineeNote','nomineeNote')}${field('last4','last4')}</div><p class="micro">${t('noIds')}</p></div></details>`;}
const isHdfc=a=>a.type==='bank'&&['hdfc','hdfcbank'].includes(a.institution.trim().toLowerCase().replace(/\s+/g,''));
function sourceLinks(a){const source=a.type==='bank'?SOURCES.bank:SOURCES.sebi;return `<div class="guide-links">${isHdfc(a)?`<a href="${SOURCES.hdfc}" target="_blank" rel="noopener noreferrer">${t('hdfcSource')} ↗</a>`:''}<a href="${source}" target="_blank" rel="noopener noreferrer">${t('source')} ↗</a>${a.type==='mf'?`<a href="${SOURCES.mf}" target="_blank" rel="noopener noreferrer">AMFI ↗</a>`:''}</div>`;}
function institutionGuidance(){return `<p>${t(draft.type+'Location')}</p>${isHdfc(draft)?`<p>${t('hdfcPath')}</p><p>${t('hdfcHolding')}</p><a href="${SOURCES.hdfc}" target="_blank" rel="noopener noreferrer">${t('hdfcSource')} ↗</a>`:''}`;}
function taskChecklist(a,state){const hdfc=isHdfc(a);let keys=state==='missing'?[hdfc?'hdfcPath':a.type+'Guide',...(hdfc?['hdfcHolding']:[]),'submitKeep','confirmRegistration']:state==='awaiting'?['followRequest','confirmRegistration','waitRegistration']:state==='confirmed'?['confirmRegistration']: [hdfc?'hdfcPath':'checkLocation','askInstitution',state==='review'?'confirmRegistration':'keepUnknown'];return `<ol class="task-checklist">${keys.map(k=>`<li><p>${t(k)}</p></li>`).join('')}</ol>`;}
function nominationGuidance(){return `<p>${t(draft.nomination==='unknown'?'checkLocation':draft.nomination==='missing'?draft.type+'Guide':'confirmRegistration')}</p>`;}
function edit(){const editing=current.accounts.some(a=>a.id===draft.id);return `${editing?'':`<p class="step-label">${t('step')} ${num(step+1)} ${t('of')} ${num(3)}</p>`}${title(t(editing?'edit':step===0?'typeQuestion':step===1?'institutionQuestion':'nomination'))}<form novalidate id="account-form" class="form-flow">${editing?`${typeChoices()}${field('institution','institution','text',true)}${nomineeChoices()}${optionalFields()}`:step===0?typeChoices():step===1?`${field('institution','institution','text',true)}<div id="institution-guidance" class="context-guide">${institutionGuidance()}</div>`:`<p class="nominee-explanation">${t('nomineeExplain')}</p>${nomineeChoices()}<section id="nomination-guidance" class="context-guide">${nominationGuidance()}</section>`}<p id="form-error" class="error" role="alert"></p><div class="button-row">${button('cancel-edit',editing?'cancel':'back','text-button')}<button type="submit" class="primary">${t(editing?'update':step===2?'add':'continue')}</button></div></form>`;}
function detail(){const a=selectedAccount(),state=attention(a);return `${button('back-list','back','text-button back-link')}${title(esc(accountTitle(a)),`${t(a.type)} · ${esc(a.institution)} ${a.owner?`· ${esc(a.owner)}`:''} ${a.last4?`· •••• ${a.last4}`:''}`)}<div class="detail-grid"><section class="task-card"><div class="section-heading"><p class="overline">${t('next')}</p>${status(a)}</div><h2>${t(taskKey(a))}</h2>${taskChecklist(a,state)}${sourceLinks(a)}<div class="button-row">${state==='missing'||state==='unknown'?button('submit-request','markSubmitted','primary'):''}${state!=='confirmed'?button('confirm-record','markConfirmed',state==='awaiting'||state==='review'?'primary':'secondary'):''}${button('edit-account','edit','text-button')}</div><p class="micro guide-boundary">${t('sourceNote')}</p>${a.type!=='bank'?`<p class="micro guide-boundary">${t('optoutNote')}</p>`:''}<p class="micro institution-note">${t('institutionOnly')}</p></section><aside class="progress-card"><h2>${t('progress')}</h2><ol class="progress-list">${['reported','submitted','confirmed'].map((key,i)=>`<li class="${a.review===key?'current':''}"><span aria-hidden="true">${i+1}</span><div><strong>${t(key)}</strong><p>${key==='reported'?t(a.nomination):key==='submitted'?a.submittedOn?date(a.submittedOn):'—':a.confirmationOn?date(a.confirmationOn):'—'}</p></div></li>`).join('')}</ol><div class="record-review">${a.nomineeNote?`<h3>${t('nominees')}</h3><p><bdi>${esc(a.nomineeNote)}</bdi></p>`:''}<h3>${t('evidence')}</h3><p>${t('checkedOn')}: ${date(a.checkedOn)}</p>${a.review==='confirmed'?`<p>${t(a.recordKind)}</p>`:''}${a.recordNote?`<p><bdi>${esc(a.recordNote)}</bdi></p>`:''}<p class="micro">${t('selfReport')}</p></div>${button('remove-account','remove','text-button danger')}</aside></div>`;}
function progressForm(){const confirming=view==='confirm';return `${title(t(confirming?'markConfirmed':'markSubmitted'))}<form novalidate id="progress-form" class="narrow-card"><p>${t(confirming?'confirmationRequired':'receiptGuide')}</p>${confirming?recordChoices():''}${dateField(confirming?'confirmationOn':'submittedOn',confirming?'confirmationDate':'submissionDate')}${field('recordNote','recordNote')}${confirming?`<label class="check-field"><input id="account-confirmationChecked" name="confirmationChecked" type="checkbox" ${draft.confirmationChecked?'checked':''} aria-describedby="account-confirmationChecked-error"><span>${t('confirmationCheck')}</span></label><p id="account-confirmationChecked-error" class="error field-error" role="alert"></p>`:''}<p class="micro">${t('noIds')}</p><p id="form-error" class="error" role="alert"></p><div class="button-row">${button('back-detail','back')}<button type="submit" class="primary">${t('update')}</button></div></form>`;}
function summary(){return `${title(t('summary'),t('summaryIntro'))}<section class="summary-card"><p class="quiet-notice">${t('summaryNotice')}</p>${current.synthetic?`<p class="sample-label">${t('sample')}</p>`:''}${orderedAccounts(current.accounts).map(a=>`<article class="summary-account">${accountRow(a,true)}<p>${t(taskKey(a))}</p>${a.nomineeNote?`<p>${t('nominees')}: <bdi>${esc(a.nomineeNote)}</bdi></p>`:''}<p class="micro">${t('checkedOn')}: ${date(a.checkedOn)} ${a.confirmationOn?`· ${t('confirmationDate')}: ${date(a.confirmationOn)}`:''}</p></article>`).join('')}<p class="micro">${t('selfReport')}</p><p class="micro">${t('boundary')}</p><div class="button-row">${button('back-list','back')}${button('print','print')}${button('export','export','primary')}</div></section>`;}
function vault(){return `${title(t(view==='save'?'save':'resume'),t('saveIntro'))}<form novalidate id="vault-form" class="narrow-card">${view==='resume'?`<div class="field"><label for="saved-file">${t('savedFile')}</label><input id="saved-file" type="file" accept=".virasat" required aria-describedby="saved-file-error"><p id="saved-file-error" class="error field-error" role="alert"></p></div>`:''}<div class="field"><label for="password">${t('password')}</label><input id="password" type="password" minlength="12" maxlength="256" required autocomplete="${view==='save'?'new-password':'current-password'}" aria-describedby="password-help password-error"><span class="help" id="password-help">${t('passwordHelp')}</span><p id="password-error" class="error field-error" role="alert"></p></div><p class="micro">${t('privacyDetail')}</p><p id="vault-status" role="status" aria-live="polite"></p><div class="button-row">${button('back-list','back')}<button type="submit" class="primary">${t(view==='save'?'save':'resume')}</button></div></form>`;}
function draw(focus=true){const active=document.activeElement,id=active?.id,selection=active&&'selectionStart' in active?[active.selectionStart,active.selectionEnd]:null,expanded=[...main.querySelectorAll('details[id][open]')].map(e=>e.id);
 document.documentElement.lang=lang;document.documentElement.dir='ltr';document.body.dataset.locale=lang;document.body.classList.toggle('language-gate',!chosen);document.querySelector('.site-header').hidden=!chosen;document.querySelector('footer').hidden=!chosen;document.querySelector('.skip').hidden=!chosen;
 document.querySelector('#home-button').setAttribute('aria-label',t('home'));document.querySelector('#home-button').title=t('home');document.querySelector('#language').value=lang;document.querySelector('#language').setAttribute('aria-label',t('language'));document.querySelector('#access-toggle').setAttribute('aria-label',t('access'));document.querySelector('.brand').href='/';document.querySelector('.skip').textContent=t('skip');
 document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));for(const [el,key] of [['size-label','textSize'],['help','privacyHelp'],['clear','clear'],['help-title','privacyHelp'],['privacy-detail','privacyDetail'],['translation-notice','translationNotice'],['help-boundary','boundary']])document.getElementById(el).textContent=t(key);for(const [el,key] of [['text-down','smaller'],['text-up','larger'],['help-close','close']])document.getElementById(el).setAttribute('aria-label',t(key));
 if(!chosen){document.querySelector('#access-panel').hidden=true;document.querySelector('#access-toggle').setAttribute('aria-expanded','false');main.innerHTML=`<section class="language-picker"><h1>Which language do you prefer?</h1><div class="language-tiles">${languages.map(([code,label],i)=>`<button type="button" data-language="${code}" lang="${code}" dir="${code==='ur'?'rtl':'ltr'}"><strong>${label}</strong></button>`).join('')}</div></section>`;main.querySelectorAll('[data-language]').forEach(e=>e.onclick=()=>chooseLanguage(e.dataset.language));return;}
 let html=view==='home'?list():view==='edit'?edit():view==='detail'?detail():['submit','confirm'].includes(view)?progressForm():view==='summary'?summary():vault();
 main.innerHTML=`<div class="app-shell">${html}</div>`;applyTextDirection();
 expanded.forEach(id=>{const el=document.getElementById(id);if(el)el.open=true;});wire();if(focus)main.focus({preventScroll:true});else if(id){const el=document.getElementById(id);el?.focus({preventScroll:true});if(selection&&el?.setSelectionRange)try{el.setSelectionRange(...selection);}catch{}}
}
function applyTextDirection(){for(const inline of document.querySelectorAll('bdi[data-text-flow]'))inline.replaceWith(...inline.childNodes);for(const el of document.querySelectorAll('h1,h2,h3,p,legend,label,button,a,strong,span'))el.removeAttribute('dir');if(lang==='ur'){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode()){const node=walker.currentNode;if(node.textContent.trim()&&!node.parentElement.closest('script,style,select,option,bdi,svg'))nodes.push(node);}for(const node of nodes){const inline=document.createElement('bdi');inline.dataset.textFlow='';inline.dir='rtl';node.replaceWith(inline);inline.append(node);}}for(const el of main.querySelectorAll('input[type=text]'))el.dir=el.dataset.datePart?'ltr':'auto';for(const el of main.querySelectorAll('input[type=password]'))el.dir='ltr';}
function go(next){if(view==='edit'&&draft&&!current.accounts.some(a=>a.id===draft.id)){unfinishedDraft={...draft};unfinishedStep=step;}view=next;draw();window.scrollTo(0,0);}
function chooseLanguage(code,push=true){window.speechSynthesis?.cancel();document.querySelector('#voice-status').textContent='';lang=code;chosen=true;if(push)history.replaceState({virasatLanguage:code},'','/');draw(false);}
function latinDigits(value){return String(value).replace(/[٠-٩۰-۹०-९০-৯]/g,c=>{const n=c.charCodeAt(0);return String(n-(n>=0x09e6?0x09e6:n>=0x0966?0x0966:n>=0x06f0?0x06f0:0x0660));});}
function updateDraft(e){const target=e.target;if(target.dataset.dateName){const name=target.dataset.dateName,parts=dateParts(name);parts[target.dataset.datePart]=latinDigits(target.value);draft[name]=/^\d{1,2}$/.test(parts.day)&&/^\d{1,2}$/.test(parts.month)&&/^\d{4}$/.test(parts.year)?`${parts.year}-${parts.month.padStart(2,'0')}-${parts.day.padStart(2,'0')}`:'';}else if(target.name in draft)draft[target.name]=target.type==='checkbox'?target.checked:target.value;const institutionGuide=document.querySelector('#institution-guidance'),nominationGuide=document.querySelector('#nomination-guidance');if(target.name==='institution'&&institutionGuide){institutionGuide.innerHTML=institutionGuidance();applyTextDirection();}if(target.name==='nomination'&&nominationGuide){nominationGuide.innerHTML=nominationGuidance();applyTextDirection();}}
function showFieldErrors(form,errors){form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));form.querySelectorAll('.field-error').forEach(el=>el.textContent='');const general=form.querySelector('#form-error');if(general)general.textContent='';for(const error of errors){const output=form.querySelector(`#${error.id}`);if(output)output.textContent=t(error.key);form.querySelectorAll(error.selector).forEach(el=>el.setAttribute('aria-invalid','true'));}applyTextDirection();if(errors.length){const input=form.querySelector(errors[0].selector);input?.focus();input?.scrollIntoView({block:'nearest'});}return errors.length===0;}
function validateVisibleFields(form){const errors=[];if(form.querySelector('#account-institution')&&!draft.institution.trim())errors.push({id:'account-institution-error',key:'requiredInstitution',selector:'#account-institution'});if(form.querySelector('#account-last4')&&draft.last4&&!/^\d{4}$/.test(draft.last4))errors.push({id:'account-last4-error',key:'invalidAccount',selector:'#account-last4'});if(form.querySelector('[name=recordKind]')&&!draft.recordKind)errors.push({id:'account-recordKind-error',key:'requiredRecord',selector:'[name=recordKind]'});for(const name of new Set([...form.querySelectorAll('[data-date-name]')].map(el=>el.dataset.dateName))){if(!draft[name]||!validDate(draft[name])||name==='confirmationOn'&&draft.submittedOn&&draft[name]<draft.submittedOn)errors.push({id:`account-${name}-error`,key:'invalidDate',selector:`[data-date-name="${name}"]`});}if(form.querySelector('[name=confirmationChecked]')&&!draft.confirmationChecked)errors.push({id:'account-confirmationChecked-error',key:'requiredCheck',selector:'[name=confirmationChecked]'});return showFieldErrors(form,errors);}
function saveAccount(value){const a=validateAccount(value),i=current.accounts.findIndex(x=>x.id===a.id);if(i<0){if(current.accounts.length>=50)throw new Error('accountLimit');current.accounts.push(a);}else current.accounts.splice(i,1,a);selected=a.id;view='detail';if(unfinishedDraft?.id===a.id)unfinishedDraft=null;draft=null;draw();window.scrollTo(0,0);live.textContent=t('updated');}
function wire(){
 const on=(id,fn)=>document.getElementById(id)?.addEventListener('click',fn);
 const continueDraft=()=>{if(unfinishedDraft){draft={...unfinishedDraft};step=unfinishedStep;}go('edit');};on('add',()=>{if(unfinishedDraft||(draft&&!current.accounts.some(a=>a.id===draft.id))){continueDraft();return;}draft=emptyAccount();step=0;go('edit');});on('continue-draft',continueDraft);on('demo',()=>{generation++;current=sampleTracker();go('home');});on('resume',()=>go('resume'));on('save',()=>go('save'));on('summary',()=>go('summary'));on('list-home',()=>go('home'));on('back-list',()=>go('home'));on('back-detail',()=>go('detail'));
 document.querySelectorAll('[data-account]').forEach(e=>e.onclick=()=>{selected=e.dataset.account;go('detail');});
 on('edit-account',()=>{draft={...selectedAccount()};go('edit');});on('cancel-edit',()=>{if(!current.accounts.some(a=>a.id===draft.id)&&step>0){step--;go('edit');}else go(current.accounts.some(a=>a.id===draft.id)?'detail':'home');});
 on('submit-request',()=>{draft={...selectedAccount(),submittedOn:today()};go('submit');});on('confirm-record',()=>{draft={...selectedAccount(),recordKind:'',confirmationOn:'',confirmationChecked:false};go('confirm');});
 on('remove-account',()=>{if(confirm(t('removeAsk'))){current.accounts=current.accounts.filter(a=>a.id!==selected);selected='';go('home');}});
 const accountForm=document.querySelector('#account-form');accountForm?.addEventListener('input',updateDraft);accountForm?.addEventListener('change',updateDraft);accountForm?.addEventListener('submit',e=>{e.preventDefault();if(!validateVisibleFields(accountForm))return;try{const previous=current.accounts.find(a=>a.id===draft.id);if(!previous&&step<2){step++;go('edit');return;}if(previous&&(previous.type!==draft.type||previous.institution!==draft.institution||previous.nomination!==draft.nomination)){draft.review='reported';draft.recordNote='';}saveAccount(draft);}catch(err){document.querySelector('#form-error').textContent=t(err.message);}});
 const progress=document.querySelector('#progress-form');progress?.addEventListener('input',updateDraft);progress?.addEventListener('change',updateDraft);progress?.addEventListener('submit',e=>{e.preventDefault();if(!validateVisibleFields(progress))return;try{draft.review=view==='confirm'?'confirmed':'submitted';if(view==='confirm'){draft.nomination='registered';draft.checkedOn=today();}saveAccount(draft);}catch(err){document.querySelector('#form-error').textContent=t(err.message);}});
 on('print',()=>window.print());on('export',()=>download(JSON.stringify(familySummary(current),null,2),'virasat-family-summary.json'));
 document.querySelector('#vault-form')?.addEventListener('submit',async e=>{e.preventDefault();const token=generation,form=e.target,status=document.querySelector('#vault-status'),submit=form.querySelector('[type=submit]'),password=document.querySelector('#password').value,saving=view==='save';const fieldErrors=[];if(password.length<12||password.length>256)fieldErrors.push({id:'password-error',key:'passwordShort',selector:'#password'});if(!saving&&!document.querySelector('#saved-file').files[0])fieldErrors.push({id:'saved-file-error',key:'invalidSave',selector:'#saved-file'});if(!showFieldErrors(form,fieldErrors))return;submit.disabled=true;status.textContent=t('saving');try{if(saving){const output=await sealCase(validateTracker(current),password);if(token!==generation)return;download(output,'family.virasat');status.textContent=t('saved');}else{const file=document.querySelector('#saved-file').files[0];if(!file||file.size>2*1024*1024)throw new Error('invalidSave');const value=validateTracker(await openCase(await file.text(),password));if(token!==generation)return;current=value;selected='';go('home');live.textContent=t('restored');}}catch(err){if(token===generation)status.textContent=t(['invalidSave','cannotUnlock','passwordShort'].includes(err.message)?err.message:'invalidSave');}finally{form.querySelector('#password').value='';submit.disabled=false;}});
}
document.querySelector('#language').innerHTML=languages.map(([code,label])=>`<option value="${code}" lang="${code}" aria-label="${label}">${label}</option>`).join('');document.querySelector('#language').onchange=e=>chooseLanguage(e.target.value);window.addEventListener('popstate',()=>{const code=pathLanguage()||history.state?.virasatLanguage;if(codes.includes(code)){lang=code;chosen=true;}if(location.pathname!=='/')history.replaceState({virasatLanguage:lang},'','/');draw(false);});document.querySelector('.brand').onclick=e=>{e.preventDefault();go('home');};document.querySelector('#home-button').onclick=()=>go('home');
document.querySelector('#access-toggle').onclick=()=>{const p=document.querySelector('#access-panel');p.hidden=!p.hidden;document.querySelector('#access-toggle').setAttribute('aria-expanded',String(!p.hidden));};document.addEventListener('click',e=>{if(!e.target.closest('.header-tools')&&!e.target.closest('#access-panel')){document.querySelector('#access-panel').hidden=true;document.querySelector('#access-toggle').setAttribute('aria-expanded','false');}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#access-panel').hidden){document.querySelector('#access-panel').hidden=true;document.querySelector('#access-toggle').setAttribute('aria-expanded','false');document.querySelector('#access-toggle').focus();}});
let textLevel=100;for(const [id,delta] of [['text-down',-10],['text-up',10]])document.getElementById(id).onclick=()=>{textLevel=Math.min(200,Math.max(90,textLevel+delta));document.documentElement.style.fontSize=`${textLevel}%`;document.querySelector('#text-level').textContent=`${textLevel}%`;document.querySelector('#text-down').disabled=textLevel===90;document.querySelector('#text-up').disabled=textLevel===200;};for(const [id,cls] of [['contrast','high-contrast'],['reduce-motion','no-motion']])document.getElementById(id).onchange=e=>document.documentElement.classList.toggle(cls,e.target.checked);
document.querySelector('#help').onclick=()=>document.querySelector('#help-dialog').showModal();document.querySelector('#help-close').onclick=()=>document.querySelector('#help-dialog').close();document.querySelector('#clear').onclick=()=>{if(current.accounts.length&&!confirm(t('clearAsk')))return;generation++;current=emptyTracker();selected='';draft=null;unfinishedDraft=null;go('home');live.textContent=t('clearDone');window.speechSynthesis?.cancel();};document.querySelector('#read-aloud').onclick=()=>{const voice=window.speechSynthesis?.getVoices().find(v=>v.localService&&v.lang.toLowerCase().startsWith(lang));if(!voice){document.querySelector('#voice-status').textContent=t('speechUnavailable');return;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t(view==='detail'?taskKey(selectedAccount()):view==='edit'?'nomination':'intro'));u.voice=voice;u.lang=lang;window.speechSynthesis.speak(u);};
draw(false);
